import { type FetchService } from './fetch';
import type { ServiceDescriptor } from '@conduit-client/utils';

// AbortError class that matches the standard AbortError
class AbortError extends Error {
    name = 'AbortError';
    constructor(message = 'This operation was aborted') {
        super(message);
    }
}

export type MockResponse = {
    status?: number;
    statusText?: string;
    ok?: boolean;
    body?: any;
    delay?: number; // Delay in milliseconds to simulate network latency
};

export type MockFetchService = {
    readonly requests: Array<Parameters<FetchService>>;
    readonly availableResponses: number;
    queueResponses: (...newResponses: Array<any>) => void;
    reset: () => void;
    readonly responsesUsed: number;
} & ((...args: any[]) => Promise<any>);

export function buildMockFetchService(
    initialResponses: Array<any> = []
): ServiceDescriptor<MockFetchService, 'fetch', '1.0'> {
    let responses: Array<any> = [...initialResponses];

    const networkAdapter = (...args: any[]) => {
        // Capture the full fetch parameters for more realistic testing
        const [_, fetchOptions = {}] = args;

        networkAdapter.requests.push(args);

        // Immediate abort detection - check if signal is already aborted
        if (fetchOptions.signal?.aborted) {
            return Promise.reject(new AbortError());
        }

        const result = responses.shift();
        if (result === undefined) {
            throw new Error('No more mock responses queued');
        }
        networkAdapter.availableResponses = responses.length;
        networkAdapter.responsesUsed++;

        if (result instanceof Error) {
            return Promise.reject(result);
        }

        // Simulate request delay if specified
        const delay = (result as MockResponse).delay || 0;

        // Create a promise that handles both delay simulation and runtime abort
        return new Promise((resolve, reject) => {
            let abortHandler: (() => void) | null = null;

            // Set up abort listener for runtime abort detection
            if (fetchOptions.signal) {
                abortHandler = () => {
                    reject(new AbortError());
                };
                fetchOptions.signal.addEventListener('abort', abortHandler);
            }

            const completeRequest = () => {
                // Clean up abort listener
                if (abortHandler && fetchOptions.signal) {
                    fetchOptions.signal.removeEventListener('abort', abortHandler);
                }

                // Check one more time if aborted during delay
                if (fetchOptions.signal?.aborted) {
                    reject(new AbortError());
                    return;
                }

                // Return successful response
                resolve({
                    ok: result.ok !== undefined ? result.ok : true,
                    statusText: result.statusText !== undefined ? result.statusText : 'ok',
                    status: result.status !== undefined ? result.status : 200,
                    json: () => Promise.resolve(result.body),
                } as Response);
            };

            if (delay > 0) {
                setTimeout(completeRequest, delay);
            } else {
                // Always use async behavior to maintain existing test expectations
                // Even without delay, tests expect async behavior for wire adapters
                setTimeout(completeRequest, 0);
            }
        });
    };

    networkAdapter.requests = [] as Array<any>;
    networkAdapter.availableResponses = responses.length;

    networkAdapter.queueResponses = (newResponses: Array<any>) => {
        responses = responses.concat(newResponses);
        networkAdapter.availableResponses = responses.length;
    };

    networkAdapter.fetch = (args: any) => networkAdapter(args);

    networkAdapter.reset = () => {
        networkAdapter.requests = [];
        responses = [];
        networkAdapter.availableResponses = 0;
        networkAdapter.responsesUsed = 0;
    };

    networkAdapter.responsesUsed = 0;
    return {
        type: 'fetch',
        version: '1.0',
        service: networkAdapter as MockFetchService,
    };
}
