import {
    resolvedPromiseLike,
    type NamedService,
    type ServiceDescriptor,
} from '@conduit-client/utils';
import type { RetryService } from '@conduit-client/service-retry/v1';

export type FetchParameters = Parameters<typeof fetch>;
export type FetchService = (...args: FetchParameters) => PromiseLike<Response>;
export type IFetchService = FetchService;
export type FetchServiceDescriptor = ServiceDescriptor<IFetchService, 'fetch', '1.0'>;
export type NamedFetchService<Name extends string = 'fetch'> = NamedService<Name, IFetchService>;
export type RequestInterceptor<Context = any> = (
    fetchArgs: FetchParameters,
    context?: Context
) => PromiseLike<FetchParameters>;
export type RetryInterceptor<Context = any> = (
    fetchArgs: FetchParameters,
    retryService?: RetryService<Response>,
    context?: Context
) => PromiseLike<Response>;
export type ResponseInterceptor<Context = any> = (
    response: Response,
    context?: Context
) => PromiseLike<Response>;
export type FinallyInterceptor<Context = any> = (context?: Context) => PromiseLike<void> | void;
export type Interceptors<Context = any> = {
    createContext?: () => Context;
    request?: RequestInterceptor<Context>[];
    retry?: RetryInterceptor<Context>;
    response?: ResponseInterceptor<Context>[];
    finally?: FinallyInterceptor<Context>[];
};
export function buildServiceDescriptor<Context = any>(
    interceptors: Interceptors<Context> = {
        request: [],
        retry: undefined,
        response: [],
        finally: [],
    },
    retryService?: RetryService<Response>
): FetchServiceDescriptor {
    return {
        type: 'fetch',
        version: '1.0',
        service: function (...args: FetchParameters) {
            // Create context per request if factory is provided
            const context = interceptors.createContext?.();

            const {
                request: requestInterceptors = [],
                retry: retryInterceptor = undefined,
                response: responseInterceptors = [],
                finally: finallyInterceptors = [],
            } = interceptors;

            const pending = requestInterceptors.reduce(
                (previousPromise, interceptor) =>
                    previousPromise.then((args) => interceptor(args, context)),
                resolvedPromiseLike(args)
            );

            return Promise.resolve(pending)
                .then((args) => {
                    if (retryInterceptor) {
                        return retryInterceptor(args, retryService, context);
                    } else {
                        // default retry logic
                        if (retryService) {
                            return retryService.applyRetry(() => fetch(...args));
                        }
                        return fetch(...args);
                    }
                })
                .then((response) => {
                    // Success path - run response interceptors
                    return responseInterceptors.reduce(
                        (previousPromise, interceptor) =>
                            previousPromise.then((response) => interceptor(response, context)),
                        resolvedPromiseLike(response)
                    );
                })
                .finally(() => {
                    // Always run finally interceptors for cleanup
                    if (finallyInterceptors.length > 0) {
                        // Run all finally interceptors sequentially
                        return finallyInterceptors.reduce(
                            (previousPromise, interceptor) =>
                                previousPromise.then(() => interceptor(context)),
                            Promise.resolve()
                        );
                    }
                });
        },
    };
}
